const fs = require('fs');
const vm = require('vm');

const rule = JSON.parse(fs.readFileSync('rule.json', 'utf8'));

let detailResult = null;
const sandbox = {
    MY_PARAMS: { bridgeBase: 'http://127.0.0.1:18002' },
    MY_URL: 'http://127.0.0.1:18002/detail?[REDACTED_QUERY]',
    input: 'http://127.0.0.1:18002/detail?[REDACTED_QUERY]',
    request: function(u) {
        return JSON.stringify({
            name: '仙逆',
            parts: [{
                play: 'cn',
                play_zh: '国语',
                part: ['第01集']
            }]
        });
    },
    setResult: function(d) {
        detailResult = d;
    }
};

vm.createContext(sandbox);
vm.runInContext(rule.detail_find_rule.replace(/^js:\s*/, ''), sandbox);

const ep = detailResult.find(x => x.col_type === 'text_3');
console.log('--- Episode URL ---');
console.log(ep.url);

const lazyPart = ep.url.substring(ep.url.indexOf('@lazyRule=') + '@lazyRule='.length);
console.log('--- Extracted lazy code ---');
console.log(lazyPart);

// Now simulate running lazy
const lazyJs = lazyPart.replace(/^\.js:\s*/, '');
const lazySandbox = {
    input: ep.url.substring(0, ep.url.indexOf('@lazyRule=')),
    MY_PARAMS: { bridgeBase: 'http://127.0.0.1:18002' },
    request: function(u) {
        // Return native response with empty headers
        return JSON.stringify({
            default: 0,
            list: [{
                url: 'http://example.com/[REDACTED_REMOTE_URL]',
                headers: {}
            }]
        });
    }
};
vm.createContext(lazySandbox);
const result = vm.runInContext(lazyJs, lazySandbox);
console.log('--- Lazy result with empty headers ---');
console.log(JSON.stringify(result));

const fs = require('fs');
const path = require('path');
const vm = require('vm');

const DEFAULT_BASE = 'http://127.0.0.1:18002';

// 1. 生成 find_rule
const findRuleCode = `js:
var d = [];
var base = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : '${DEFAULT_BASE}';
while (base.length > 0 && base.charAt(base.length - 1) === '/') {
    base = base.substring(0, base.length - 1);
}

var curUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
var targetUrl = '';

if (curUrl && curUrl.indexOf('/list') !== -1) {
    var pIdx = curUrl.indexOf('/list');
    targetUrl = base + curUrl.substring(pIdx);
} else {
    var cate = (typeof MY_CATE !== 'undefined' && MY_CATE) ? MY_CATE : '20';
    var page = (typeof MY_PAGE !== 'undefined' && MY_PAGE) ? MY_PAGE : '1';
    targetUrl = base + '/list?channel=' + cate + '&page=' + page;
}

var res = request(targetUrl);
var data = JSON.parse(res);
if (data && data.error) {
    throw new Error('DMGHG List Error: ' + data.error);
}
var list = (data && data.items) ? data.items : (Array.isArray(data) ? data : []);
for (var i = 0; i < list.length; i++) {
    var it = list[i];
    var title = it.name || it.title || '';
    var pic = it.pic || '';
    var id = it.id || '';
    var desc = it.continu || it.type || '';
    d.push({
        title: title,
        desc: desc,
        pic_url: pic ? (pic + '@Referer=' + base + '/') : '',
        url: base + '/detail?id=' + id,
        col_type: 'movie_3'
    });
}
setResult(d);`;

// 2. 生成 search_rule & searchFind
const searchRuleCode = `js:
var d = [];
var base = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : '${DEFAULT_BASE}';
while (base.length > 0 && base.charAt(base.length - 1) === '/') {
    base = base.substring(0, base.length - 1);
}

var curUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
var kw = '';
if (typeof KEYWORD !== 'undefined' && KEYWORD) {
    kw = KEYWORD;
} else if (typeof MY_KEYWORD !== 'undefined' && MY_KEYWORD) {
    kw = MY_KEYWORD;
} else if (typeof KEY !== 'undefined' && KEY) {
    kw = KEY;
} else if (curUrl) {
    var match = curUrl.match(/[?&]key=([^&]+)/);
    if (match) {
        kw = decodeURIComponent(match[1]);
    }
}
var page = (typeof MY_PAGE !== 'undefined' && MY_PAGE) ? MY_PAGE : '1';
if (curUrl && curUrl.match(/[?&]page=([^&]+)/)) {
    page = curUrl.match(/[?&]page=([^&]+)/)[1];
}

var targetUrl = base + '/search?key=' + encodeURIComponent(kw) + '&page=' + encodeURIComponent(page);

var res = request(targetUrl);
var data = JSON.parse(res);
if (data && data.error) {
    throw new Error('DMGHG Search Error: ' + data.error);
}
var list = (data && data.items) ? data.items : (Array.isArray(data) ? data : []);
for (var i = 0; i < list.length; i++) {
    var it = list[i];
    var title = it.name || it.title || '';
    var pic = it.pic || '';
    var id = it.id || '';
    var desc = it.continu || it.type || '';
    d.push({
        title: title,
        desc: desc,
        pic_url: pic ? (pic + '@Referer=' + base + '/') : '',
        url: base + '/detail?id=' + id,
        col_type: 'movie_3'
    });
}
setResult(d);`;

// 3. 生成 detail_find_rule
// 注意：选集的 @lazyRule 生成逻辑：当 headers 为空时，绝不添加 Referer 或 User-Agent，直接原样返回 finalUrl！
const detailRuleCode = `js:
var d = [];
var base = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : '${DEFAULT_BASE}';
while (base.length > 0 && base.charAt(base.length - 1) === '/') {
    base = base.substring(0, base.length - 1);
}

var curUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
var id = '';
if (curUrl) {
    var match = curUrl.match(/[?&]id=([^&]+)/);
    if (match) {
        id = match[1];
    } else {
        var pIdx = curUrl.indexOf('/detail');
        if (pIdx !== -1) {
            id = curUrl.substring(pIdx).replace(/^\\/detail\\/?/, '');
        }
    }
}

var targetUrl = base + '/detail?id=' + encodeURIComponent(id);

var res = request(targetUrl);
var data = JSON.parse(res);
if (data && data.error) {
    throw new Error('DMGHG Detail Error: ' + data.error);
}
var title = data.name || data.title || '';
var pic = data.pic || '';
var intro = data.content || data.desc || '';
var actor = data.actor ? ('主演：' + data.actor) : '';
var director = data.director ? ('导演：' + data.director) : '';
var descText = [actor, director, intro].filter(Boolean).join('\\n');

d.push({
    title: '剧名：' + title,
    desc: descText,
    pic_url: pic ? (pic + '@Referer=' + base + '/') : '',
    url: curUrl,
    col_type: 'pic_1_card'
});

// 单独定义的 lazy 模板函数（运行时转为字符串拼接入选集卡片 URL）
var lazyTemplate = (() => {
    var b = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : '__BASE__';
    while (b.length > 0 && b.charAt(b.length - 1) === '/') { b = b.substring(0, b.length - 1); }
    var cur = (typeof input !== 'undefined' && input) ? input : '';
    var pIdx = cur.indexOf('/play?');
    if (pIdx !== -1) { cur = b + cur.substring(pIdx); }
    var res = request(cur);
    var pData = JSON.parse(res);
    if (pData && pData.error) { throw new Error('DMGHG Play Error: ' + pData.error); }
    if (!pData || !pData.list || pData.list.length === 0) { throw new Error('DMGHG: No stream in play response'); }
    var item = pData.list[pData.default || 0] || pData.list[0];
    var finalUrl = item.url || '';
    if (!finalUrl) { throw new Error('DMGHG: empty stream URL'); }
    var hdrs = item.headers || {};
    var headerParts = [];
    for (var k in hdrs) {
        if (Object.prototype.hasOwnProperty.call(hdrs, k)) {
            headerParts.push(k + '@' + hdrs[k]);
        }
    }
    if (headerParts.length > 0) {
        return finalUrl + ';{' + headerParts.join('&&') + '}';
    }
    return finalUrl;
}).toString();

var parts = data.parts || [];
for (var p = 0; p < parts.length; p++) {
    var partGroup = parts[p];
    var lineName = partGroup.play_zh || partGroup.play || ('线路 ' + (p + 1));
    var playLine = partGroup.play || '';

    d.push({
        title: '【' + lineName + '】',
        col_type: 'text_1'
    });

    var epList = partGroup.part || [];
    for (var e = 0; e < epList.length; e++) {
        var epName = epList[e];
        var playTargetUrl = base + '/play?id=' + encodeURIComponent(id) + '&part=' + encodeURIComponent(epName) + '&play=' + encodeURIComponent(playLine);
        var lazyJs = '(' + lazyTemplate.replace('__BASE__', base) + ')()';

        d.push({
            title: epName,
            url: playTargetUrl + '@lazyRule=.js:' + lazyJs,
            col_type: 'text_3'
        });
    }
}
setResult(d);`;

const rule = {
    title: "动漫共和国概念版",
    author: "DeepCloud Rule Engineer",
    version: 1,
    url: `${DEFAULT_BASE}/list?channel=fyclass&page=fypage`,
    col_type: "movie_3",
    class_name: "日漫&国漫&剧场&美漫&特摄&少儿&动态漫&猜你想看",
    class_url: "20&21&22&23&25&32&26&27",
    find_rule: findRuleCode,
    search_url: `${DEFAULT_BASE}/search?key=**&page=fypage`,
    searchFind: searchRuleCode,
    search_rule: searchRuleCode,
    detail_col_type: "movie_1_vertical_pic",
    detail_find_rule: detailRuleCode
};

fs.writeFileSync('rule.json', JSON.stringify(rule, null, 2), 'utf8');
console.log('✅ rule.json generated.');

// 本地 VM 严格测试 detail_find_rule 以及生成的 lazyRule
let detailResult = null;
const sandbox = {
    MY_PARAMS: { bridgeBase: DEFAULT_BASE },
    MY_URL: `${DEFAULT_BASE}/detail?id=181655`,
    input: `${DEFAULT_BASE}/detail?id=181655`,
    request: function(u) {
        return JSON.stringify({
            name: '仙逆',
            parts: [{
                play: 'cn',
                play_zh: '国语',
                part: ['第01集']
            }]
        });
    },
    setResult: function(d) {
        detailResult = d;
    }
};

vm.createContext(sandbox);
vm.runInContext(rule.detail_find_rule.replace(/^js:\s*/, ''), sandbox);

const ep = detailResult.find(x => x.col_type === 'text_3');
console.log('Episode Card Title:', ep.title);

const lazyPart = ep.url.substring(ep.url.indexOf('@lazyRule=') + '@lazyRule='.length);
const lazyJs = lazyPart.replace(/^\.js:\s*/, '');
console.log('Lazy JS code sample:', lazyJs.substring(0, 100));

// 1. 空 headers 测试：应当返回纯 finalUrl，无 ;{...}
const emptyHeadersSandbox = {
    input: ep.url.substring(0, ep.url.indexOf('@lazyRule=')),
    MY_PARAMS: { bridgeBase: DEFAULT_BASE },
    request: function(u) {
        return JSON.stringify({
            default: 0,
            list: [{
                url: 'http://cdn.example.com/[REDACTED_REMOTE_URL]',
                headers: {}
            }]
        });
    }
};
vm.createContext(emptyHeadersSandbox);
const emptyRes = vm.runInContext(lazyJs, emptyHeadersSandbox);
console.log('Empty headers result:', emptyRes);
if (emptyRes !== 'http://cdn.example.com/[REDACTED_REMOTE_URL]') {
    throw new Error('Expected exact finalUrl without headers, got: ' + emptyRes);
}

// 2. 有 headers 测试：应当返回 finalUrl + ;{User-Agent@PC}
const withHeadersSandbox = {
    input: ep.url.substring(0, ep.url.indexOf('@lazyRule=')),
    MY_PARAMS: { bridgeBase: DEFAULT_BASE },
    request: function(u) {
        return JSON.stringify({
            default: 0,
            list: [{
                url: 'http://cdn.example.com/[REDACTED_REMOTE_URL]',
                headers: { 'User-Agent': 'PC' }
            }]
        });
    }
};
vm.createContext(withHeadersSandbox);
const withRes = vm.runInContext(lazyJs, withHeadersSandbox);
console.log('With headers result:', withRes);
if (withRes !== 'http://cdn.example.com/[REDACTED_REMOTE_URL]') {
    throw new Error('Expected headers annotation, got: ' + withRes);
}

